import{_ as a,o as t,c as i,al as r}from"./chunks/framework.kcAuNBLo.js";const p=JSON.parse('{"title":"Terms and Conditions of Service","description":"","frontmatter":{},"headers":[],"relativePath":"support/terms-and-conditions.md","filePath":"support/terms-and-conditions.md"}'),o={name:"support/terms-and-conditions.md"};function n(s,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="terms-and-conditions-of-service" tabindex="-1">Terms and Conditions of Service <a class="header-anchor" href="#terms-and-conditions-of-service" aria-label="Permalink to &quot;Terms and Conditions of Service&quot;">​</a></h1><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p><em><strong>Last Updated:</strong> 23 Apr 2026</em></p></div><p>Welcome to <strong>Material Home Assistant</strong>. These Terms and Conditions (&quot;Terms&quot;) govern your access to and use of the services, software code, website, and applications provided by Material Home Assistant (&quot;we&quot;, &quot;our&quot;, or &quot;the Service&quot;).</p><p>By using the Service, you agree to be bound by these Terms in their entirety. If you do not agree with any part of these terms, please do not use the Service.</p><h2 id="_1-description-of-service" tabindex="-1">1. Description of Service <a class="header-anchor" href="#_1-description-of-service" aria-label="Permalink to &quot;1. Description of Service&quot;">​</a></h2><p>Material Home Assistant provides tools, integrations, and interfaces for home automation management based on the Home Assistant ecosystem. Certain advanced features are offered exclusively through paid subscription plans.</p><h2 id="_2-registration-and-account" tabindex="-1">2. Registration and Account <a class="header-anchor" href="#_2-registration-and-account" aria-label="Permalink to &quot;2. Registration and Account&quot;">​</a></h2><p>You are responsible for maintaining the confidentiality of your credentials and for all activities that occur under your account. You agree to provide accurate, complete, and up-to-date information.</p><h2 id="_3-subscriptions-and-payments" tabindex="-1">3. Subscriptions and Payments <a class="header-anchor" href="#_3-subscriptions-and-payments" aria-label="Permalink to &quot;3. Subscriptions and Payments&quot;">​</a></h2><h3 id="_3-1-subscription-plans" tabindex="-1">3.1 Subscription Plans <a class="header-anchor" href="#_3-1-subscription-plans" aria-label="Permalink to &quot;3.1 Subscription Plans&quot;">​</a></h3><p>Access to &quot;Premium&quot; or &quot;Pro&quot; features is subject to the payment of a periodic fee as indicated on the pricing page. We reserve the right to modify rates upon notice; such changes will take effect at the start of the next billing cycle.</p><h3 id="_3-2-payment-processing-stripe" tabindex="-1">3.2 Payment Processing (Stripe) <a class="header-anchor" href="#_3-2-payment-processing-stripe" aria-label="Permalink to &quot;3.2 Payment Processing (Stripe)&quot;">​</a></h3><p>Payments are handled via the third-party platform <strong>Stripe</strong>. By subscribing, you agree to Stripe&#39;s terms of service. Material Home Assistant does not store or directly process sensitive payment data, ensuring compliance with PCI-DSS standards.</p><h2 id="_4-cancellation-and-withdrawal-policy" tabindex="-1">4. Cancellation and Withdrawal Policy <a class="header-anchor" href="#_4-cancellation-and-withdrawal-policy" aria-label="Permalink to &quot;4. Cancellation and Withdrawal Policy&quot;">​</a></h2><h3 id="_4-1-cancellation" tabindex="-1">4.1 Cancellation <a class="header-anchor" href="#_4-1-cancellation" aria-label="Permalink to &quot;4.1 Cancellation&quot;">​</a></h3><p>You may cancel your subscription at any time through your account settings. Access will remain active until the end of the current paid period, after which the account will revert to the free plan (if available).</p><h3 id="_4-2-waiver-of-right-of-withdrawal-digital-content" tabindex="-1">4.2 Waiver of Right of Withdrawal (Digital Content) <a class="header-anchor" href="#_4-2-waiver-of-right-of-withdrawal-digital-content" aria-label="Permalink to &quot;4.2 Waiver of Right of Withdrawal (Digital Content)&quot;">​</a></h3><p>As these are digital services provided immediately upon payment, you agree that the performance of the contract begins instantly and, in accordance with applicable regulations (e.g., EU Consumer Rights Directive), you <strong>expressly waive your 14-day right of withdrawal</strong>.</p><h2 id="_5-refunds-and-credits" tabindex="-1">5. Refunds and Credits <a class="header-anchor" href="#_5-refunds-and-credits" aria-label="Permalink to &quot;5. Refunds and Credits&quot;">​</a></h2><h3 id="_5-1-no-refund-policy" tabindex="-1">5.1 No-Refund Policy <a class="header-anchor" href="#_5-1-no-refund-policy" aria-label="Permalink to &quot;5.1 No-Refund Policy&quot;">​</a></h3><p>Due to the digital nature of the services provided, no monetary refunds are issued for partially used periods or early cancellations.</p><h3 id="_5-2-downgrades-and-stripe-credit" tabindex="-1">5.2 Downgrades and Stripe Credit <a class="header-anchor" href="#_5-2-downgrades-and-stripe-credit" aria-label="Permalink to &quot;5.2 Downgrades and Stripe Credit&quot;">​</a></h3><p>In the event of a downgrade to a lower-value plan before expiration, the proportional difference (pro-rata) will not be refunded to the original payment method but will be converted into <strong>Stripe Credit</strong>. This credit will be automatically applied to future renewals or purchases made exclusively within Material Home Assistant.</p><h2 id="_6-intellectual-property-and-licensing" tabindex="-1">6. Intellectual Property and Licensing <a class="header-anchor" href="#_6-intellectual-property-and-licensing" aria-label="Permalink to &quot;6. Intellectual Property and Licensing&quot;">​</a></h2><p>All code, trademarks, and graphics are the property of Material Home Assistant. The subscription grants a <strong>personal, non-exclusive, and non-transferable</strong> license for use. Redistribution, reverse engineering, or resale of the software code without written authorization is strictly prohibited.</p><h2 id="_7-limitation-of-liability" tabindex="-1">7. Limitation of Liability <a class="header-anchor" href="#_7-limitation-of-liability" aria-label="Permalink to &quot;7. Limitation of Liability&quot;">​</a></h2><h3 id="_7-1-as-is" tabindex="-1">7.1 &quot;As Is&quot; <a class="header-anchor" href="#_7-1-as-is" aria-label="Permalink to &quot;7.1 &quot;As Is&quot;&quot;">​</a></h3><p>The Service is provided &quot;as is&quot; and &quot;as available&quot;. We do not guarantee that the component will be error-free or perfectly compatible with every future version of Home Assistant.</p><h3 id="_7-2-third-party-dependencies" tabindex="-1">7.2 Third-Party Dependencies <a class="header-anchor" href="#_7-2-third-party-dependencies" aria-label="Permalink to &quot;7.2 Third-Party Dependencies&quot;">​</a></h3><p>We are not responsible for malfunctions resulting from Home Assistant core updates, third-party cloud service interruptions, or the user&#39;s internet connectivity issues.</p><h3 id="_7-3-critical-usage" tabindex="-1">7.3 Critical Usage <a class="header-anchor" href="#_7-3-critical-usage" aria-label="Permalink to &quot;7.3 Critical Usage&quot;">​</a></h3><p>The Service is <strong>not designed</strong> for the control of critical safety equipment (e.g., fire suppression systems, medical devices, primary security locks). Use of the component in such scenarios is at the user&#39;s sole risk and peril.</p><h2 id="_8-privacy" tabindex="-1">8. Privacy <a class="header-anchor" href="#_8-privacy" aria-label="Permalink to &quot;8. Privacy&quot;">​</a></h2><p>Personal data processing is carried out in accordance with our <strong>Privacy Policy</strong>, which describes how we collect and protect your information in compliance with current regulations (GDPR).</p><h2 id="_9-governing-law-and-jurisdiction" tabindex="-1">9. Governing Law and Jurisdiction <a class="header-anchor" href="#_9-governing-law-and-jurisdiction" aria-label="Permalink to &quot;9. Governing Law and Jurisdiction&quot;">​</a></h2><p>These Terms are governed by the laws of [Insert State/Country]. Any dispute shall be subject to the exclusive jurisdiction of the courts of [Insert City].</p><h2 id="_10-contacts" tabindex="-1">10. Contacts <a class="header-anchor" href="#_10-contacts" aria-label="Permalink to &quot;10. Contacts&quot;">​</a></h2><p>For assistance or questions regarding these Terms:</p><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p></p><ul><li><strong>Email:</strong> <a href="mailto:support@materialhomeassistant.com" target="_blank" rel="noreferrer">support@materialhomeassistant.com</a></li><li><strong>Website:</strong> <a href="https://www.materialhomeassistant.com" target="_blank" rel="noreferrer">https://www.materialhomeassistant.com</a></li></ul></div>',39)])])}const m=a(o,[["render",n]]);export{p as __pageData,m as default};
